            domains.append(domain)

    results = {}

    for domain in domains:
        try:
            params = {}
            if API_KEY:
                params['key'] = API_KEY

            response = requests.get(
                f'http://ip-api.com/json/{domain}',
                params=params,
                timeout=10
            )

            if response.status_code == 200:
                results[domain] = json.loads(response.text)
            else:
                results[domain] = None
        except Exception:
            results[domain] = None

    return results

