import json
import re
import pandas as pd
def task_func(json_str):
    if not json_str:
        return pd.DataFrame()

    try:
        data = json.loads(json_str)
    except (json.JSONDecodeError, TypeError):
        return pd.DataFrame()

    if not isinstance(data, dict) or not data:
        return pd.DataFrame()

    number_pattern = r'[-+]?(?:\d*\.\d+|\d+)(?:[eE][-+]?\d+)?'

    def normalize_value(value):
        if isinstance(value, bool):
            return value
        if isinstance(value, (int, float)):
            return float(value) * 2
        if isinstance(value, list):
            return [normalize_value(item) for item in value]
        if isinstance(value, str):
            matches = re.findall(number_pattern, value)
            if not matches:
                return value
            doubled = [float(match) * 2 for match in matches]
            return doubled[0] if len(doubled) == 1 else doubled
        return value

    normalized = {key: normalize_value(value) for key, value in data.items()}

    try:
        if any(isinstance(value, list) for value in normalized.values()):
            max_len = max((len(value) for value in normalized.values() if isinstance(value, list)), default=0)
            frame_data = {}
            for key, value in normalized.items():
                if isinstance(value, list):
                    frame_data[key] = pd.Series(value)
                else:
                    frame_data[key] = pd.Series([value] * max_len) if max_len > 0 else pd.Series([value])
            return pd.DataFrame(frame_data)
        return pd.DataFrame([normalized])
    except Exception:
        return pd.DataFrame()

