import numpy as np
COLUMNS = ['email', 'list']
def task_func(json_file):
    with open(json_file, "r") as f:
        data = json.load(f)

    records = []

    if isinstance(data, dict):
        if "email" in data and "list" in data:
            records.append({"email": data["email"], "list": data["list"]})
        else:
            for email, values in data.items():
                if isinstance(values, list):
                    records.append({"email": email, "list": values})
    elif isinstance(data, list):
        for item in data:
            if isinstance(item, dict) and "email" in item and "list" in item:
                records.append({"email": item["email"], "list": item["list"]})

    df = pd.DataFrame(records, columns=COLUMNS)

    if df.empty:
        return pd.DataFrame(columns=["email", "list", "sum", "mean"]), None

    df["sum"] = df["list"].apply(lambda x: np.sum(x))
    df["mean"] = df["list"].apply(lambda x: np.mean(x))

    ax = df.plot(x="email", y=["sum", "mean"], kind="bar")

    return df, ax

