import pandas as pd
import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        data = json.loads(json_data)
    except (json.JSONDecodeError, TypeError):
        raise ValueError("JSON data is malformed")

    if not data:
        raise ValueError("JSON data is empty")

    rows = []

    if isinstance(data, list):
        for item in data:
            if not isinstance(item, dict):
                raise ValueError("JSON data must contain dictionaries")
            if "Country" not in item or "Population" not in item:
                raise ValueError("Missing Country or Population field")
            rows.append((item["Country"], item["Population"]))
    elif isinstance(data, dict):
        if "Country" in data and "Population" in data:
            rows.append((data["Country"], data["Population"]))
        else:
            for country, population in data.items():
                rows.append((country, population))
    else:
        raise ValueError("JSON data must be a dictionary or list")

    cleaned_rows = []

    for country, population in rows:
        if not isinstance(country, str):
            raise ValueError("Country names must be strings")

        if isinstance(population, bool) or not isinstance(population, (int, float)):
            raise ValueError("Populations must be numeric")

        if not math.isfinite(population) or population < 0:
            raise ValueError("Populations must be non-negative finite numbers")

        cleaned_rows.append({
            "Country": country,
            "Population": math.floor(population)
        })

    if not cleaned_rows:
        raise ValueError("JSON data is empty")

    df = pd.DataFrame(cleaned_rows, columns=["Country", "Population"])

    file_path = os.path.join(output_dir, file_name)

    try:
        df.to_csv(file_path, index=False)
    except OSError as e:
        raise IOError("File cannot be written to the specified directory") from e

    return file_path, df

