import json
import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    data = json.loads(json_str)

    email_pattern = r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b'

    def process(value):
        if value is None:
            return None
        if isinstance(value, dict):
            return {k: process(v) for k, v in value.items() if v is not None}
        if isinstance(value, list):
            return [process(item) for item in value if item is not None]
        if isinstance(value, str):
            return re.sub(email_pattern, REPLACE_NONE, value)
        return value

    processed_data = process(data)

    values = []

    def collect(value):
        if isinstance(value, dict):
            for v in value.values():
                collect(v)
        elif isinstance(value, list):
            for item in value:
                collect(item)
        else:
            values.append(value)

    collect(processed_data)

    return {
        "data": processed_data,
        "value_counts": Counter(values)
    }

